{
  "analysis": [
    {
      "layout": "P",
      "strengths": "All headers and numerical ranges remain whole, and metric labels wrap at natural word boundaries. The table has a relatively compact height and makes the control and variant columns easy to compare in the full view.",
      "faults": "The first viewport shows the metric and control mean but cuts through the control interval; the variant, lift and p-value require scrolling. Several metric labels occupy two lines.",
      "spatial_logic": "It gives the metric column enough width for mostly short labels and reserves full one-line widths for the confidence intervals, accepting substantial horizontal scrolling."
    },
    {
      "layout": "Q",
      "strengths": "Like P, it keeps headers and numerical ranges whole and uses natural breaks in the metric labels. Its wider metric column provides a little more breathing room.",
      "faults": "The extra 10 px produces no reduction in row height or line count in this render. It also reveals less of the control interval in the first viewport and increases the scrolling distance.",
      "spatial_logic": "It follows P's allocation but gives the row labels a little more space, without a visible payoff for this particular content."
    },
    {
      "layout": "R",
      "strengths": "It is narrower than P and Q, and the initial viewport reaches the end of the control group. Headers and words remain intact.",
      "faults": "Both monetary and time confidence intervals break across lines, making their endpoints harder to read as ranges. The narrower metric column adds a line to the cart abandonment label, and the table becomes taller.",
      "spatial_logic": "It reduces scrolling by taking width from the metric and both interval columns, trading horizontal space for additional row height and fragmented ranges."
    },
    {
      "layout": "S",
      "strengths": "All seven columns are present in the viewport without horizontal scrolling, so their overall arrangement is visible at once.",
      "faults": "Headers, words, numbers, percentages and interval endpoints split into fragments. The resulting tall rows and irregular line breaks make lookup and comparison very difficult, despite the absence of scrolling.",
      "spatial_logic": "It divides the viewport among every column, giving the metric the largest share but leaving too little text width for even short numerical entries."
    }
  ],
  "insights": "The confidence intervals need enough width to keep each range together; their line breaks in R cost more reading effort than the modest reduction in scrolling saves. P uses that space effectively, while Q's extra metric width has no visible benefit. Fitting all seven columns into 360 px forces severe fragmentation, so a fitting design can only be a compromise under the fixed typography and padding.",
  "best": ["P"],
  "done": false,
  "designs": [
    {
      "widths": [284, 73, 134, 71, 131, 73, 76],
      "idea": "Give the metric column enough width for every label on one line while retaining P's whole numerical ranges. This should produce a shorter, more regular table, at the cost of more scrolling and less numerical content in the initial viewport."
    },
    {
      "widths": [115, 40, 44, 40, 44, 38, 38],
      "idea": "A fitting alternative to S: shift a little width toward metric labels, which carry the lookup task, while keeping all seven columns visible. Numbers and headers will still fragment severely; the improvement over S is uncertain and needs a render."
    }
  ]
